import "strconv"

func fizzBuzz(n int) []string {
	hasil := []string{}
	for i := 1; i <= n; i++ {
		switch {
		case i%15 == 0:
			hasil = append(hasil, "FizzBuzz")
		case i%3 == 0:
			hasil = append(hasil, "Fizz")
		case i%5 == 0:
			hasil = append(hasil, "Buzz")
		default:
			hasil = append(hasil, strconv.Itoa(i))
		}
	}
	return hasil
}
